      label: '股票查询',
    },
    {
      key: '/stock-trackings',
      icon: <EyeOutlined />,
      label: '股票追踪',
    },
    {
      key: '/simulation',
      icon: <WalletOutlined />,
      label: '账户模拟',
    },
    {
      key: '/backtest',
      icon: <LineChartOutlined />,
      label: '回测',
    },
    {
      key: '/agent-chat',
