import React, { useState, useEffect } from 'react';
import {
  Table,
  Card,
  Button,
  Tag,
  Typography,
  Space,
  message,
  Spin,
  Empty,
  Modal,
  Descriptions,
  Table as DetailTable,
} from 'antd';
import { ReloadOutlined, EyeOutlined, DeleteOutlined } from '@ant-design/icons';
import { Popconfirm } from 'antd';
import api from '@/services/api';

const { Title, Text } = Typography;

interface BacktestRecord {
  id: string;
  startTime: string;
  endTime: string;
  minConfidence: number;
  maxConfidence: number;
  directions: string[];
  stopLoss: string;
  takeProfit: string;
  period: string;
  totalTrades: number;
  winningTrades: number;
  losingTrades: number;
  winRate: string;
  totalReturn: string;
  maxDrawdown: string;
  avgReturn: string;
  trades: Array<{
    signalId: string;
    stockCode: string;
    stockName: string;
    direction: string;
    entryPrice: number;
    exitPrice: number;
    return: number;
    exitReason: string;
    entryTime: string;
    exitTime: string;
  }>;
  createdAt: string;
}

const BacktestPage: React.FC = () => {
  const [loading, setLoading] = useState(false);
  const [data, setData] = useState<BacktestRecord[]>([]);
  const [detailModalVisible, setDetailModalVisible] = useState(false);
  const [selectedRecord, setSelectedRecord] = useState<BacktestRecord | null>(null);

  const fetchData = async () => {
    setLoading(true);
    try {
      const response = await api.get('/backtest/records');
      setData(response.data || []);
    } catch (error) {
      message.error('获取回测记录失败');
      console.error('Fetch backtest records error:', error);
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    fetchData();
  }, []);

  const handleViewDetail = (record: BacktestRecord) => {
    setSelectedRecord(record);
    setDetailModalVisible(true);
  };

  const handleDelete = async (id: string) => {
    try {
      await api.delete(`/backtest/records/${id}`);
      message.success('删除成功');
      fetchData();
    } catch (error) {
      message.error('删除失败');
      console.error('Delete backtest record error:', error);
    }
  };

  const formatDate = (dateString: string) => {
    if (!dateString) return '-';
    const date = new Date(dateString);
    return date.toLocaleString('zh-CN');
  };

  const formatPercent = (value: string | number) => {
    const num = typeof value === 'string' ? parseFloat(value) : value;
    return `${(num * 100).toFixed(2)}%`;
  };

  const getDirectionTag = (directions: string[]) => {
    return directions.map((dir) => {
      const color = dir === 'buy' || dir === 'bullish' ? 'red' : 'green';
      const text = dir === 'buy' || dir === 'bullish' ? '买入' : '卖出';
      return <Tag key={dir} color={color}>{text}</Tag>;
    });
  };

  const columns = [
    {
      title: '回测时间',
      dataIndex: 'createdAt',
      key: 'createdAt',
      width: 180,
      render: (time: string) => formatDate(time),
    },
    {
      title: '回测区间',
      key: 'timeRange',
      width: 220,
      render: (_: unknown, record: BacktestRecord) => (
