} from '@ant-design/icons';
import { useUser } from '@/contexts/UserContext';
import { Bubble } from '@ant-design/x';
import ReactMarkdown from 'react-markdown';
import type { PluggableList } from 'unified';
import styles from './index.less';

// 内联样式 - 超紧凑模式
const inlineStyles = `
